// src/api/tmdbApi.js
import axios from "axios";

const TMDB_API_KEY = "b56be59cfcfc26fbad50e51fb6341736"; // 발급받은 키 입력
const TMDB_BASE_URL = "https://api.themoviedb.org/3";

export const getPosterFromTMDB = async (movieTitle, openDate) => {
  try {
    const response = await axios.get(`${TMDB_BASE_URL}/search/movie`, {
      params: {
        api_key: TMDB_API_KEY,
        query: movieTitle,
        language: "ko-KR",
      },
    });

    const results = response.data.results;

    if (results.length === 0) return null;

    // 개봉일 기반으로 가장 유사한 영화 선택
    const matched = results.find((movie) => {
      if (!openDate || !movie.release_date) return false;
      return movie.release_date.startsWith(openDate.slice(0, 4)); // 연도 비교
    });

    const targetMovie = matched || results[0];
    return targetMovie.poster_path
      ? `https://image.tmdb.org/t/p/w200${targetMovie.poster_path}`
      : null;
  } catch (error) {
    console.error("TMDB 포스터 가져오기 실패:", error);
    return null;
  }
};
